"use strict";
// Groups the digits of a whole number in threes, and counts how often it did.
console.log("ledger-digits is ready");
let groupings = 0;
exports.group = function group(whole) {
  groupings += 1;
  return String(whole).replace(/\B(?=(\d{3})+$)/g, ",");
};
exports.groupings = () => groupings;
